const names = ['Worker', 'SharedWorker', 'BroadcastChannel', 'importScripts', 'postMessage', 'indexedDB', 'caches', 'XMLHttpRequest', 'EventSource'];
const avail = (o) => names.filter((n) => { try { return o && o[n] !== undefined && o[n] !== null; } catch { return false; } });
console.log('global', avail(globalThis).join(',') || '(none)');
const repl = require('repl'); const { PassThrough } = require('stream');
const r = repl.start({ input: new PassThrough(), output: new PassThrough(), terminal: false });
console.log('repl context', avail(r.context).join(',') || '(none)', 'same global?', r.context === globalThis);
r.close();
const ph = require('perf_hooks');
const res = (now) => { let m = Infinity, last = now(); for (let i = 0; i < 200000 && m > 0.0005; i++) { const t = now(); if (t > last) { m = Math.min(m, t - last); } last = t; } return m < 0.001 ? '<1us' : m < 0.02 ? '1-20us' : '>=20us'; };
console.log('perf_hooks now resolution', res(() => ph.performance.now()), 'global performance', res(() => performance.now()), 'same object', ph.performance === globalThis.performance);
const h = ph.monitorEventLoopDelay(); console.log('eld resolution option ok', typeof h.enable);
console.log('eventLoopUtilization/active idle fields numbers', Object.values(ph.performance.eventLoopUtilization()).every((v) => typeof v === 'number'));
console.log('dc channels for internal', typeof require('diagnostics_channel').channel('undici:request:create').publish);
const sw = require('stream/web'); console.log('stream/web keys capability-free', Object.keys(sw).filter((k) => /Worker|Channel|Port|fetch/i.test(k)).join(',') || 'yes');
const d = require('domain').create(); console.log('domain members', Object.keys(d).filter((k) => !k.startsWith('_')).sort().join(','));
